/**
 * Phase 4 Pipeline -- Stage 7: Deployment Generator
 *
 * Generates Cloud Run deployment descriptors: multi-stage Dockerfile,
 * Knative serving manifest (cloud-run-service.yaml), Cloud Build pipeline
 * (cloudbuild.yaml), and an example environment variable file (.env.example).
 *
 * TypeScript target: Node 20 multi-stage Docker build.
 * Rust target: Rust 1.77 / Debian bookworm-slim multi-stage Docker build.
 *
 * All generated files carry a "do not edit manually" header.
 *
 * Exports:
 *   - generateDeployment(context) -- pipeline entry point
 *
 * Error codes:
 *   ECLI-P4-070  Missing prerequisite stage output (erp-target-resolution)
 *   ECLI-P4-071  Deployment file write failure
 */

import { mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import type {
  Phase4Context,
  Phase4StageOutput,
  DeploymentOutput,
  DeploymentFile,
  ERPResolution,
} from '../types.js';
import { hasTemplateSupport } from '../types.js';
import { createSpan, endSpan, emitSpan } from '../../phase2/telemetry.js';

// ============================================================================
// Constants
// ============================================================================

const DIR_MODE = 0o700;
const FILE_MODE = 0o600;

// ============================================================================
// Dockerfile Generation
// ============================================================================

/**
 * Generate a multi-stage Dockerfile for a TypeScript / Node 20 Cloud Run service.
 */
function tsDockerfile(): string {
  return [
    '# Generated by Phase 4 pipeline — do not edit manually',
    '',
    '# Stage 1: build',
    'FROM node:20-slim AS builder',
    'WORKDIR /app',
    'COPY package*.json ./',
    'RUN npm ci',
    'COPY . .',
    'RUN npm run build',
    '',
    '# Stage 2: runtime',
    'FROM node:20-slim',
    'WORKDIR /app',
    'ENV NODE_ENV=production',
    'COPY --from=builder /app/dist ./dist',
    'COPY --from=builder /app/node_modules ./node_modules',
    'EXPOSE 8080',
    'CMD ["node", "dist/server/main.js"]',
    '',
  ].join('\n');
}

/**
 * Generate a multi-stage Dockerfile for a Rust / Axum Cloud Run service.
 */
function rustDockerfile(): string {
  return [
    '# Generated by Phase 4 pipeline — do not edit manually',
    '',
    '# Stage 1: build',
    'FROM rust:1.77 AS builder',
    'WORKDIR /app',
    'COPY Cargo.toml Cargo.lock ./',
    'COPY src ./src',
    'RUN cargo build --release',
    '',
    '# Stage 2: runtime (minimal debian image)',
    'FROM debian:bookworm-slim',
    'RUN apt-get update && apt-get install -y --no-install-recommends \\',
    '    ca-certificates \\',
    '    && rm -rf /var/lib/apt/lists/*',
    'COPY --from=builder /app/target/release/server /usr/local/bin/server',
    'EXPOSE 8080',
    'CMD ["server"]',
    '',
  ].join('\n');
}

// ============================================================================
// Cloud Run Service YAML
// ============================================================================

/**
 * Generate a Knative Serving manifest for Cloud Run.
 */
function cloudRunServiceYaml(traceIdShort: string): string {
  return [
    '# Generated by Phase 4 pipeline — do not edit manually',
    'apiVersion: serving.knative.dev/v1',
    'kind: Service',
    'metadata:',
    `  name: mvp-${traceIdShort}`,
    '  annotations:',
    '    run.googleapis.com/ingress: internal-and-cloud-load-balancing',
    'spec:',
    '  template:',
    '    metadata:',
    '      annotations:',
    '        autoscaling.knative.dev/minScale: "0"',
    '        autoscaling.knative.dev/maxScale: "10"',
    '        run.googleapis.com/cpu-throttling: "false"',
    '    spec:',
    '      serviceAccountName: mvp-service@PROJECT_ID.iam.gserviceaccount.com',
    '      containerConcurrency: 80',
    '      containers:',
    '        - image: IMAGE_URL',
    '          ports:',
    '            - containerPort: 8080',
    '          env:',
    '            - name: PORT',
    '              value: "8080"',
    '            - name: DB_CONNECTION_STRING',
    '              value: "" # Set via Secret Manager',
    '            - name: ERP_SURFACE_URL',
    '              value: "" # Set during deployment',
    '          resources:',
    '            limits:',
    '              cpu: "1"',
    '              memory: 512Mi',
    '',
  ].join('\n');
}

// ============================================================================
// Cloud Build YAML
// ============================================================================

/**
 * Generate a Cloud Build pipeline YAML.
 */
function cloudBuildYaml(): string {
  return [
    '# Generated by Phase 4 pipeline — do not edit manually',
    'steps:',
    '  - name: gcr.io/cloud-builders/docker',
    '    args:',
    "      - 'build'",
    "      - '-t'",
    "      - 'IMAGE_URL'",
    "      - '.'",
    '',
    '  - name: gcr.io/cloud-builders/docker',
    '    args:',
    "      - 'push'",
    "      - 'IMAGE_URL'",
    '',
    '  - name: gcr.io/google.com/cloudsdktool/cloud-sdk',
    '    entrypoint: gcloud',
    '    args:',
    "      - 'run'",
    "      - 'deploy'",
    "      - 'SERVICE_NAME'",
    "      - '--image'",
    "      - 'IMAGE_URL'",
    "      - '--region'",
    "      - 'us-central1'",
    "      - '--platform'",
    "      - 'managed'",
    "      - '--quiet'",
    '',
    'images:',
    "  - 'IMAGE_URL'",
    '',
  ].join('\n');
}

// ============================================================================
// .env.example
// ============================================================================

/**
 * Generate a .env.example with all required environment variables.
 */
function envExample(): string {
  return [
    '# Generated by Phase 4 pipeline — do not edit manually',
    '# Copy this file to .env and fill in values before running locally.',
    '# Never commit .env to version control.',
    '',
    'PORT=8080',
    'DB_CONNECTION_STRING=',
    'ERP_SURFACE_URL=',
    'GCP_PROJECT_ID=',
    'SERVICE_ACCOUNT_EMAIL=',
    'OTEL_EXPORTER_OTLP_ENDPOINT=',
    'LOG_LEVEL=info',
    '',
  ].join('\n');
}

// ============================================================================
// File Writing
// ============================================================================

/**
 * Write a deployment file to disk, creating parent directories as needed.
 */
function writeDeploymentFile(absPath: string, content: string): void {
  const dir = absPath.substring(0, absPath.lastIndexOf('/'));
  mkdirSync(dir, { recursive: true, mode: DIR_MODE });
  try {
    writeFileSync(absPath, content, { encoding: 'utf-8', mode: FILE_MODE });
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : String(err);
    throw new Error(`ECLI-P4-071: Failed to write deployment file ${absPath}: ${message}`);
  }
}

// ============================================================================
// Public: Pipeline Entry Point
// ============================================================================

/**
 * Stage 7 entry point: generate Cloud Run deployment descriptors.
 *
 * Reads ERPResolution from context.stageOutputs.get('erp-target-resolution'),
 * derives a short trace ID suffix, and writes all deployment files to
 * phase4/deployment/.
 *
 * @param context - The Phase 4 pipeline context
 * @returns Stage output describing success or failure
 */
export function generateDeployment(context: Phase4Context): Phase4StageOutput {
  const startTime = Date.now();
  const rootSpan = createSpan('deployment-generation', 'generate-deployment', {
    phase4Dir: context.phase4Dir,
    traceId: context.traceId,
  });

  try {
    // Verify ERP target resolution completed
    const erpStage = context.stageOutputs.get('erp-target-resolution');
    if (!erpStage || erpStage.status !== 'completed') {
      throw new Error(
        'ECLI-P4-070: ERP target resolution not available on context. ' +
        'Ensure the erp-target-resolution stage completed successfully before running deployment-generation.',
      );
    }
    const erpResolution = erpStage.data as ERPResolution;
    void erpResolution;

    // Resolve implementation language and short trace ID
    const language = context.phase3Artifacts.implementationLanguage;

    // Non-TS/Rust languages handled by Ruflo swarm
    if (!hasTemplateSupport(language)) {
      const span = endSpan(rootSpan, 'ok', { delegated: true, language });
      emitSpan(span);
      return {
        stage: 'deployment-generation',
        status: 'completed',
        data: { files: [], cloudRunService: 'delegated-to-ruflo' } satisfies DeploymentOutput,
        artifacts: [],
        timing: Date.now() - startTime,
        summary: `Deployment for ${language} delegated to Ruflo swarm.`,
      };
    }

    const traceIdShort = context.traceId.slice(0, 8);
    const isTs = language === 'typescript';

    // Output directory: phase4/deployment/
    const deployDir = join(context.phase4Dir, 'deployment');
    mkdirSync(deployDir, { recursive: true, mode: DIR_MODE });

    const deployFiles: DeploymentFile[] = [];
    const writtenPaths: string[] = [];

    const genSpan = createSpan(
      'deployment-generation',
      'generate-files',
      { language, traceIdShort },
      rootSpan.spanId,
    );

    // Dockerfile (language-specific multi-stage build)
    const dockerfileContent = isTs ? tsDockerfile() : rustDockerfile();
    const dockerfilePath = join(deployDir, 'Dockerfile');
    writeDeploymentFile(dockerfilePath, dockerfileContent);
    deployFiles.push({ relativePath: 'deployment/Dockerfile', content: dockerfileContent, kind: 'deployment' });
    writtenPaths.push(dockerfilePath);

    // cloud-run-service.yaml (Knative serving manifest)
    const crServiceContent = cloudRunServiceYaml(traceIdShort);
    const crServicePath = join(deployDir, 'cloud-run-service.yaml');
    writeDeploymentFile(crServicePath, crServiceContent);
    deployFiles.push({ relativePath: 'deployment/cloud-run-service.yaml', content: crServiceContent, kind: 'deployment' });
    writtenPaths.push(crServicePath);

    // cloudbuild.yaml (Cloud Build pipeline)
    const cloudBuildContent = cloudBuildYaml();
    const cloudBuildPath = join(deployDir, 'cloudbuild.yaml');
    writeDeploymentFile(cloudBuildPath, cloudBuildContent);
    deployFiles.push({ relativePath: 'deployment/cloudbuild.yaml', content: cloudBuildContent, kind: 'deployment' });
    writtenPaths.push(cloudBuildPath);

    // .env.example
    const envContent = envExample();
    const envPath = join(deployDir, '.env.example');
    writeDeploymentFile(envPath, envContent);
    deployFiles.push({ relativePath: 'deployment/.env.example', content: envContent, kind: 'deployment' });
    writtenPaths.push(envPath);

    const cloudRunService = `mvp-${traceIdShort}`;

    const finalGenSpan = endSpan(genSpan, 'ok', { filesGenerated: writtenPaths.length, cloudRunService });
    emitSpan(finalGenSpan);

    const finalRootSpan = endSpan(rootSpan, 'ok', {
      language,
      traceIdShort,
      filesGenerated: writtenPaths.length,
      cloudRunService,
    });
    emitSpan(finalRootSpan);

    const timing = Date.now() - startTime;
    const output: Phase4StageOutput = {
      stage: 'deployment-generation',
      status: 'completed',
      data: {
        files: deployFiles,
        cloudRunService,
      } satisfies DeploymentOutput,
      artifacts: writtenPaths,
      timing,
      summary:
        `Generated deployment descriptors (${language}): ` +
        `Dockerfile, cloud-run-service.yaml, cloudbuild.yaml, .env.example ` +
        `for Cloud Run service "${cloudRunService}" ` +
        `(${writtenPaths.length} files in ${timing}ms)`,
    };

    context.stageOutputs.set('deployment-generation', output);
    return output;
  } catch (err: unknown) {
    const errorMessage = err instanceof Error ? err.message : String(err);

    const finalRootSpan = endSpan(rootSpan, 'error', { error: errorMessage });
    emitSpan(finalRootSpan);

    const timing = Date.now() - startTime;
    const output: Phase4StageOutput = {
      stage: 'deployment-generation',
      status: 'failed',
      data: { error: errorMessage },
      artifacts: [],
      timing,
      summary: `Deployment generation failed: ${errorMessage}`,
    };

    context.stageOutputs.set('deployment-generation', output);
    return output;
  }
}
